  <link rel="icon" type="image/svg+xml" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><text y='.9em' font-size='90'>🌍</text></svg>">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Merriweather:wght@700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --red: #C41E3A; --red-dark: #A31830; --navy: #1B3A5C; --navy-light: #2a527a;
      --white: #FFFFFF; --gray-50: #F8F9FA; --gray-100: #F1F3F5; --gray-200: #E9ECEF;
      --gray-300: #DEE2E6; --gray-400: #CED4DA; --gray-500: #ADB5BD; --gray-600: #6C757D;
      --gray-700: #495057; --gray-800: #343A40; --gray-900: #212529; --gray-950: #0D1117;
      --shadow-sm: 0 1px 2px rgba(0,0,0,.05); --shadow: 0 4px 6px rgba(0,0,0,.1);
      --shadow-md: 0 6px 12px rgba(0,0,0,.15); --shadow-lg: 0 10px 25px rgba(0,0,0,.2);
      --radius-sm: 4px; --radius: 8px; --radius-md: 12px; --radius-lg: 16px; --radius-xl: 24px;
      --transition: all .25s ease; --font-sans: 'Inter',system-ui,-apple-system,sans-serif;
      --font-serif: 'Merriweather',Georgia,serif;
    }
    html { scroll-behavior: smooth; }
    body { font-family: var(--font-sans); font-size: 16px; line-height: 1.6; color: var(--gray-800); background: var(--white); overflow-x: hidden; }
    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; height: auto; display: block; }
    ul { list-style: none; }
    .container { max-width: 1200px; margin: 0 auto; padding: 0 24px; }
    .btn { display: inline-flex; align-items: center; justify-content: center; gap: 8px; padding: 14px 28px; font-family: var(--font-sans); font-size: 15px; font-weight: 600; border-radius: var(--radius); border: none; cursor: pointer; transition: var(--transition); white-space: nowrap; }
    .btn-primary { background: var(--red); color: var(--white); }
    .btn-primary:hover { background: var(--red-dark); transform: translateY(-2px); box-shadow: var(--shadow-md); }
    .btn-secondary { background: var(--navy); color: var(--white); }
    .btn-secondary:hover { background: var(--navy-light); transform: translateY(-2px); box-shadow: var(--shadow-md); }
    .btn-outline { background: transparent; color: var(--white); border: 2px solid var(--white); }
    .btn-outline:hover { background: var(--white); color: var(--navy); }
    .btn-lg { padding: 18px 36px; font-size: 16px; }
    .section-label { display: inline-block; font-size: 12px; font-weight: 700; letter-spacing: 1.5px; text-transform: uppercase; color: var(--red); margin-bottom: 12px; }
    .section-title { font-family: var(--font-serif); font-size: clamp(28px, 4vw, 42px); font-weight: 700; color: var(--navy); line-height: 1.2; margin-bottom: 16px; }
    .section-desc { font-size: 17px; color: var(--gray-600); max-width: 640px; line-height: 1.7; }

    /* Header */
    .header { position: fixed; top: 0; left: 0; right: 0; background: var(--white); z-index: 1000; transition: var(--transition); }
    .header.scrolled { box-shadow: var(--shadow); }
    .header-inner { display: flex; align-items: center; justify-content: space-between; padding: 16px 24px; max-width: 1400px; margin: 0 auto; }
    .logo { display: flex; align-items: center; gap: 12px; font-weight: 800; font-size: 18px; color: var(--navy); }
    .logo svg { width: 40px; height: 40px; }
    .logo span { color: var(--red); }
    .nav-desktop { display: flex; align-items: center; gap: 32px; }
    .nav-links { display: flex; align-items: center; gap: 28px; }
    .nav-links a { font-size: 14px; font-weight: 500; color: var(--gray-700); transition: var(--transition); }
    .nav-links a:hover { color: var(--red); }
    .nav-utils { display: flex; align-items: center; gap: 16px; font-size: 13px; color: var(--gray-500); }
    .nav-utils span { color: var(--gray-300); }
    .btn-donate-header { padding: 10px 20px; font-size: 13px; }
    .hamburger { display: none; flex-direction: column; gap: 5px; background: none; border: none; cursor: pointer; padding: 8px; }
    .hamburger span { width: 24px; height: 2px; background: var(--navy); border-radius: 2px; transition: var(--transition); }
    .hamburger.active span:nth-child(1) { transform: rotate(45deg) translate(5px, 5px); }
    .hamburger.active span:nth-child(2) { opacity: 0; }
    .hamburger.active span:nth-child(3) { transform: rotate(-45deg) translate(5px, -5px); }

    /* Mobile Nav */
    .nav-mobile { display: none; position: fixed; top: 72px; left: 0; right: 0; bottom: 0; background: var(--white); padding: 24px; z-index: 999; transform: translateX(-100%); transition: transform .3s ease; }
    .nav-mobile.active { transform: translateX(0); }
    .nav-mobile a { display: block; padding: 16px 0; font-size: 16px; font-weight: 500; color: var(--gray-700); border-bottom: 1px solid var(--gray-200); }
    .nav-mobile a:hover { color: var(--red); }
    .nav-mobile-utils { margin-top: 24px; display: flex; flex-wrap: wrap; gap: 12px; font-size: 13px; color: var(--gray-500); }

    /* Hero */
    .hero { min-height: 100vh; display: flex; align-items: center; background: linear-gradient(135deg, var(--navy) 0%, #0f2439 100%); position: relative; overflow: hidden; padding-top: 72px; }
    .hero::before { content: ''; position: absolute; inset: 0; background: url('https://images.unsplash.com/photo-1469571486292-0ba58a3f068b?w=1920&q=80') center/cover no-repeat; opacity: .15; }
    .hero-content { position: relative; z-index: 1; max-width: 720px; }
    .hero-title { font-family: var(--font-serif); font-size: clamp(36px, 5vw, 60px); font-weight: 700; color: var(--white); line-height: 1.15; margin-bottom: 24px; }
    .hero-subtitle { font-size: clamp(16px, 2vw, 19px); color: rgba(255,255,255,.85); line-height: 1.7; margin-bottom: 36px; max-width: 580px; }
    .hero-btns { display: flex; flex-wrap: wrap; gap: 16px; }
    .hero-img-mobile { display: none; }

    /* Mission */
    .mission { padding: 100px 0; background: var(--gray-50); }
    .mission-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 64px; align-items: center; }
    .mission-img { border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-lg); }
    .mission-img img { width: 100%; height: 400px; object-fit: cover; }
    .mission-content { padding-right: 32px; }
    .mission-text { margin-top: 24px; font-size: 17px; color: var(--gray-600); line-height: 1.8; }
    .mission-principles { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 24px; }
    .mission-principles span { display: inline-block; padding: 8px 16px; background: var(--white); border: 1px solid var(--gray-200); border-radius: 100px; font-size: 13px; font-weight: 600; color: var(--navy); }

    /* Impact Stats */
    .impact { padding: 80px 0; background: var(--red); }
    .impact .section-title { color: var(--white); }
    .impact .section-desc { color: rgba(255,255,255,.8); }
    .stats-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 32px; margin-top: 48px; }
    .stat-item { text-align: center; padding: 32px 16px; background: rgba(255,255,255,.1); border-radius: var(--radius-lg); backdrop-filter: blur(10px); }
    .stat-number { font-family: var(--font-serif); font-size: clamp(36px, 4vw, 52px); font-weight: 700; color: var(--white); line-height: 1; }
    .stat-number .prefix { font-size: .6em; vertical-align: super; }
    .stat-label { font-size: 14px; font-weight: 600; color: rgba(255,255,255,.9); margin-top: 8px; text-transform: uppercase; letter-spacing: .5px; }
    .stat-desc { font-size: 13px; color: rgba(255,255,255,.7); margin-top: 8px; }

    /* Programs */
    .programs { padding: 100px 0; }
    .programs-header { text-align: center; margin-bottom: 56px; }
    .programs-header .section-desc { margin: 0 auto; }
    .accordion { max-width: 800px; margin: 0 auto; }
    .accordion-item { border: 1px solid var(--gray-200); border-radius: var(--radius); margin-bottom: 12px; overflow: hidden; background: var(--white); transition: var(--transition); }
    .accordion-item:hover { box-shadow: var(--shadow); }
    .accordion-trigger { width: 100%; display: flex; align-items: center; justify-content: space-between; padding: 20px 24px; background: none; border: none; cursor: pointer; text-align: left; font-size: 16px; font-weight: 600; color: var(--navy); transition: var(--transition); }
    .accordion-trigger svg { width: 20px; height: 20px; transition: transform .3s ease; flex-shrink: 0; }
    .accordion-item.active .accordion-trigger svg { transform: rotate(180deg); }
    .accordion-content { max-height: 0; overflow: hidden; transition: max-height .35s ease; }
    .accordion-item.active .accordion-content { max-height: 300px; }
    .accordion-body { padding: 0 24px 24px; font-size: 15px; color: var(--gray-600); line-height: 1.7; }

    /* Get Involved */
    .get-involved { padding: 100px 0; background: var(--gray-50); }
    .get-involved-header { text-align: center; margin-bottom: 56px; }
    .get-involved-header .section-desc { margin: 0 auto; }
    .involve-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 32px; }
    .involve-card { background: var(--white); border-radius: var(--radius-lg); padding: 32px; box-shadow: var(--shadow-sm); border: 1px solid var(--gray-200); transition: var(--transition); }
    .involve-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
    .involve-icon { width: 56px; height: 56px; background: rgba(196,30,58,.1); border-radius: var(--radius); display: flex; align-items: center; justify-content: center; margin-bottom: 20px; }
    .involve-icon svg { width: 28px; height: 28px; color: var(--red); }
    .involve-card h3 { font-size: 18px; font-weight: 700; color: var(--navy); margin-bottom: 12px; }
    .involve-card p { font-size: 15px; color: var(--gray-600); line-height: 1.6; margin-bottom: 20px; }
    .involve-card .btn { width: 100%; }

    /* News */
    .news { padding: 100px 0; }
    .news-header { display: flex; align-items: flex-end; justify-content: space-between; margin-bottom: 48px; }
    .news-nav-btns { display: flex; gap: 12px; }
    .news-nav-btn { width: 44px; height: 44px; border-radius: 50%; border: 1px solid var(--gray-300); background: var(--white); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: var(--transition); }
    .news-nav-btn:hover { background: var(--navy); color: var(--white); border-color: var(--navy); }
    .news-nav-btn svg { width: 20px; height: 20px; }
    .carousel { overflow: hidden; margin: 0 -24px; padding: 0 24px; }
    .carousel-track { display: flex; transition: transform .4s ease; gap: 24px; }
    .news-card { flex: 0 0 calc(33.333% - 16px); min-width: 280px; background: var(--white); border-radius: var(--radius-lg); overflow: hidden; box-shadow: var(--shadow-sm); border: 1px solid var(--gray-200); }
    .news-card-img { height: 200px; overflow: hidden; }
    .news-card-img img { width: 100%; height: 100%; object-fit: cover; transition: transform .4s ease; }
    .news-card:hover .news-card-img img { transform: scale(1.05); }
    .news-card-body { padding: 24px; }
    .news-card-date { font-size: 12px; color: var(--gray-500); font-weight: 500; text-transform: uppercase; letter-spacing: .5px; margin-bottom: 8px; }
    .news-card h3 { font-size: 17px; font-weight: 700; color: var(--navy); line-height: 1.4; margin-bottom: 12px; }
    .news-card p { font-size: 14px; color: var(--gray-600); line-height: 1.6; }

    /* Donate CTA */
    .donate-cta { padding: 100px 0; background: linear-gradient(135deg, var(--navy) 0%, #0f2439 100%); position: relative; overflow: hidden; }
    .donate-cta::before { content: ''; position: absolute; inset: 0; background: url('https://images.unsplash.com/photo-1488521787991-ed7bbaae773c?w=1920&q=80') center/cover no-repeat; opacity: .1; }
    .donate-cta-inner { position: relative; z-index: 1; text-align: center; max-width: 640px; margin: 0 auto; }
    .donate-cta .section-title { color: var(--white); }
    .donate-cta .section-desc { color: rgba(255,255,255,.8); margin: 0 auto 40px; }
    .impact-table { background: rgba(255,255,255,.08); border-radius: var(--radius-lg); padding: 32px; margin-bottom: 40px; backdrop-filter: blur(10px); }
    .impact-table h4 { color: var(--white); font-size: 14px; font-weight: 600; margin-bottom: 20px; text-transform: uppercase; letter-spacing: 1px; }
    .impact-grid { display: grid; grid-template-columns: repeat(2, 1fr); gap: 16px; }
    .impact-row { display: flex; justify-content: space-between; align-items: center; padding: 12px 16px; background: rgba(255,255,255,.05); border-radius: var(--radius); }
    .impact-amount { font-weight: 700; color: var(--white); font-size: 15px; }
    .impact-desc { font-size: 13px; color: rgba(255,255,255,.7); }
    .donate-cta .btn { min-width: 200px; }

    /* Footer */
    .footer { background: var(--gray-950); color: var(--gray-400); padding: 64px 0 32px; }
    .footer-grid { display: grid; grid-template-columns: 2fr repeat(3, 1fr); gap: 48px; padding-bottom: 48px; border-bottom: 1px solid var(--gray-800); }
    .footer-brand p { font-size: 14px; line-height: 1.7; margin: 16px 0 24px; }
    .footer-social { display: flex; gap: 16px; }
    .footer-social a { width: 40px; height: 40px; border-radius: 50%; background: var(--gray-800); display: flex; align-items: center; justify-content: center; transition: var(--transition); }
    .footer-social a:hover { background: var(--red); }
    .footer-social svg { width: 18px; height: 18px; color: var(--gray-400); }
    .footer-col h4 { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: 1px; color: var(--white); margin-bottom: 20px; }
    .footer-col ul li { margin-bottom: 12px; }
    .footer-col ul li a { font-size: 14px; transition: var(--transition); }
    .footer-col ul li a:hover { color: var(--white); }
    .footer-bottom { display: flex; justify-content: space-between; align-items: center; padding-top: 32px; font-size: 13px; }
    .footer-tagline { display: flex; align-items: center; gap: 8px; }
    .footer-tagline svg { width: 20px; height: 20px; color: var(--red); }

    /* Donation Modal */
    .modal-overlay { position: fixed; inset: 0; background: rgba(0,0,0,.6); z-index: 2000; display: flex; align-items: center; justify-content: center; padding: 24px; opacity: 0; visibility: hidden; transition: all .3s ease; }
    .modal-overlay.active { opacity: 1; visibility: visible; }
    .modal { background: var(--white); border-radius: var(--radius-xl); max-width: 480px; width: 100%; max-height: 90vh; overflow-y: auto; transform: translateY(20px); transition: transform .3s ease; }
    .modal-overlay.active .modal { transform: translateY(0); }
    .modal-header { padding: 24px 24px 0; text-align: center; }
    .modal-header h2 { font-family: var(--font-serif); font-size: 24px; color: var(--navy); }
    .modal-header p { font-size: 14px; color: var(--gray-600); margin-top: 8px; }
    .modal-close { position: absolute; top: 16px; right: 16px; width: 36px; height: 36px; border-radius: 50%; border: none; background: var(--gray-100); cursor: pointer; display: flex; align-items: center; justify-content: center; transition: var(--transition); }
    .modal-close:hover { background: var(--gray-200); }
    .modal-body { padding: 24px; }
    .donation-amounts { display: grid; grid-template-columns: repeat(3, 1fr); gap: 12px; margin-bottom: 20px; }
    .amount-btn { padding: 16px; border: 2px solid var(--gray-200); border-radius: var(--radius); background: var(--white); cursor: pointer; font-size: 16px; font-weight: 600; color: var(--navy); transition: var(--transition); }
    .amount-btn:hover, .amount-btn.selected { border-color: var(--red); background: rgba(196,30,58,.05); color: var(--red); }
    .custom-amount { position: relative; }
    .custom-amount input { width: 100%; padding: 14px 14px 14px 32px; border: 2px solid var(--gray-200); border-radius: var(--radius); font-size: 16px; transition: var(--transition); }
    .custom-amount input:focus { outline: none; border-color: var(--red); }
    .custom-amount span { position: absolute; left: 14px; top: 50%; transform: translateY(-50%); font-size: 16px; font-weight: 600; color: var(--gray-500); }
    .impact-legend { background: var(--gray-50); border-radius: var(--radius); padding: 16px; margin-bottom: 20px; }
    .impact-legend p { font-size: 13px; color: var(--gray-600); line-height: 1.5; }
    .impact-legend strong { color: var(--navy); }
    .donate-submit { width: 100%; padding: 16px; font-size: 16px; }
    .modal-footer { text-align: center; padding: 0 24px 24px; font-size: 12px; color: var(--gray-500); }

    /* Responsive */
    @media (max-width: 1024px) {
      .nav-desktop { display: none; }
      .hamburger { display: flex; }
      .nav-mobile { display: block; }
      .mission-grid { grid-template-columns: 1fr; gap: 40px; }
      .mission-content { padding-right: 0; }
      .mission-img { order: -1; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .get-involved-header .section-desc { margin: 0 auto; }
      .news-card { flex: 0 0 calc(50% - 12px); }
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 768px) {
      .hero { min-height: auto; padding: 120px 0 80px; }
      .hero-btns { flex-direction: column; }
      .hero-btns .btn { width: 100%; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); gap: 16px; }
      .stat-item { padding: 24px 12px; }
      .involve-grid { grid-template-columns: 1fr; }
      .news-header { flex-direction: column; align-items: flex-start; gap: 20px; }
      .footer-grid { grid-template-columns: 1fr; gap: 32px; }
      .footer-bottom { flex-direction: column; gap: 16px; text-align: center; }
      .impact-grid { grid-template-columns: 1fr; }
      .donation-amounts { grid-template-columns: repeat(2, 1fr); }
    }
    @media (max-width: 480px) {
      .stat-item { padding: 20px 8px; }
      .stat-number { font-size: 32px; }
    }

    /* Animations */
    @keyframes fadeInUp { from { opacity: 0; transform: translateY(30px); } to { opacity: 1; transform: translateY(0); } }
    .animate { opacity: 0; }
    .animate.visible { animation: fadeInUp .6s ease forwards; }
    .delay-1 { animation-delay: .1s; }
    .delay-2 { animation-delay: .2s; }
    .delay-3 { animation-delay: .3s; }
    .delay-4 { animation-delay: .4s; }
  </style>
</head>
<body>
  <!-- Header -->
  <header class="header" id="header">
    <div class="header-inner">
      <a href="#" class="logo">
        <svg viewBox="0 0 40 40" fill="none"><circle cx="20" cy="20" r="18" stroke="#C41E3A" stroke-width="2"/><path d="M20 6a14 14 0 010 28 14 14 0 010-28z" fill="#1B3A5C"/><path d="M12 20h16M20 12v16" stroke="#C41E3A" stroke-width="2" stroke-linecap="round"/></svg>
        Global Aid <span>Alliance</span>
      </a>
      <nav class="nav-desktop">
        <ul class="nav-links">
          <li><a href="#about">About Us</a></li>
          <li><a href="#programs">Disaster Relief</a></li>
          <li><a href="#programs">Programs & Services</a></li>
          <li><a href="#involved">Volunteer</a></li>
          <li><a href="#footer">Find Local Chapter</a></li>
        </ul>
        <div class="nav-utils">
          <span>Sign In</span>·<a href="#">Contact Us</a>·<a href="#">Español</a>
          <button class="btn btn-primary btn-donate-header" onclick="openDonateModal()">Donate</button>
        </div>
      </nav>
      <button class="hamburger" id="hamburger" aria-label="Toggle menu">
        <span></span><span></span><span></span>
      </button>
    </div>
    <nav class="nav-mobile" id="navMobile">
      <a href="#about" onclick="closeMobileNav()">About Us</a>
      <a href="#programs" onclick="closeMobileNav()">Disaster Relief</a>
      <a href="#programs" onclick="closeMobileNav()">Programs & Services</a>
      <a href="#involved" onclick="closeMobileNav()">Volunteer</a>
      <a href="#footer" onclick="closeMobileNav()">Find Local Chapter</a>
      <button class="btn btn-primary" onclick="openDonateModal(); closeMobileNav();" style="margin-top:24px;width:100%">Donate Now</button>
      <div class="nav-mobile-utils">
        <span>Sign In</span>·<a href="#">Contact Us</a>·<a href="#">Español</a>
      </div>
    </nav>
  </header>

  <!-- Hero -->
  <section class="hero">
    <div class="container">
      <div class="hero-content">
        <h1 class="hero-title">When Disaster Strikes, We're There</h1>
        <p class="hero-subtitle">From hurricanes and wildfires to global health emergencies, Global Aid Alliance delivers immediate relief and long-term recovery support to communities in crisis.</p>
        <div class="hero-btns">
          <button class="btn btn-primary btn-lg" onclick="openDonateModal()">
            <svg width="20" height="20" fill="none" stroke="currentColor" stroke-width="2"><path d="M12 2L12 6M12 18L12 22M2 12L6 12M18 12L22 12"/></svg>
            Donate Now
          </button>
          <a href="#involved" class="btn btn-outline btn-lg">Become a Volunteer</a>
        </div>
      </div>
    </div>
  </section>

  <!-- Mission -->
