  <script>
    // Mobile menu
    const hamburger = document.getElementById('hamburger');
    const navMobile = document.getElementById('navMobile');
    hamburger.addEventListener('click', () => {
      hamburger.classList.toggle('active');
      navMobile.classList.toggle('active');
    });
    function closeMobileNav() {
      hamburger.classList.remove('active');
      navMobile.classList.remove('active');
    }

    // Header scroll
    window.addEventListener('scroll', () => {
      document.getElementById('header').classList.toggle('scrolled', window.scrollY > 20);
    });

    // Donation Modal
    let selectedAmount = 50;
    const impactMessages = {
      25: 'Provides 5 emergency blankets for displaced families',
      50: 'Supplies a family with food and water for one week',
      100: 'Funds emergency shelter materials for a household',
      250: 'Equips a volunteer with disaster response training',
      500: 'Provides clean water access for a community for a month',
      1000: 'Trains and equips an entire disaster response team'
    };

    function openDonateModal() {
      document.getElementById('donateModal').classList.add('active');
      document.body.style.overflow = 'hidden';
    }
    function closeDonateModal() {
      document.getElementById('donateModal').classList.remove('active');
      document.body.style.overflow = '';
    }
    document.querySelectorAll('.amount-btn').forEach(btn => {
      btn.addEventListener('click', () => {
        document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
        btn.classList.add('selected');
        selectedAmount = parseInt(btn.dataset.amount);
        document.getElementById('customAmount').value = '';
        updateImpactLegend(selectedAmount);
      });
    });
    document.getElementById('customAmount').addEventListener('input', (e) => {
      const val = parseInt(e.target.value);
      if (val && val > 0) {
        document.querySelectorAll('.amount-btn').forEach(b => b.classList.remove('selected'));
        selectedAmount = val;
        updateImpactLegend(val);
      }
    });
    function updateImpactLegend(amount) {
      const legend = document.getElementById('impactLegend');
      if (impactMessages[amount]) {
        legend.innerHTML = `<p><strong>$${amount}</strong> — ${impactMessages[amount]}</p>`;
      } else {
        legend.innerHTML = `<p><strong>$${amount}</strong> — Every dollar counts toward saving lives</p>`;
      }
    }
    function submitDonation() {
      const custom = document.getElementById('customAmount').value;
      const amount = custom ? parseInt(custom) : selectedAmount;
      if (amount && amount > 0) {
        alert(`Thank you for your generous donation of $${amount}! This would process to a payment gateway in production.`);
        closeDonateModal();
      }
    }
    document.getElementById('donateModal').addEventListener('click', (e) => {
      if (e.target === e.currentTarget) closeDonateModal();
    });

    // Accordion
    document.querySelectorAll('.accordion-trigger').forEach(trigger => {
      trigger.addEventListener('click', () => {
        const item = trigger.parentElement;
        const wasActive = item.classList.contains('active');
        document.querySelectorAll('.accordion-item').forEach(i => i.classList.remove('active'));
        if (!wasActive) item.classList.add('active');
      });
    });

    // News Carousel
    let carouselPos = 0;
    const track = document.getElementById('carouselTrack');
    function getCardWidth() {
      return track.querySelector('.news-card').offsetWidth + 24;
    }
    function moveCarousel(dir) {
      const containerWidth = document.querySelector('.carousel').offsetWidth;
      const cards = track.querySelectorAll('.news-card');
      const totalWidth = cards.length * getCardWidth();
      const visibleWidth = containerWidth - 48;
      const maxOffset = totalWidth - visibleWidth;
      carouselPos = Math.max(0, Math.min(carouselPos - dir * getCardWidth(), maxOffset));
      track.style.transform = `translateX(-${carouselPos}px)`;
    }

    // Counter Animation
    function animateCounters() {
      document.querySelectorAll('.counter').forEach(counter => {
        if (counter.dataset.animated) return;
        const target = parseInt(counter.dataset.target);
        const duration = 2000;
        const start = performance.now();
        function update(now) {
          const elapsed = now - start;
          const progress = Math.min(elapsed / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          let value = Math.floor(eased * target);
          if (target >= 1000000) {
            counter.textContent = (value / 1000000).toFixed(1) + 'M';
          } else if (target >= 1000) {
            counter.textContent = (value / 1000000).toFixed(1) + 'M';
          } else {
            counter.textContent = value.toLocaleString();
          }
          if (progress < 1) requestAnimationFrame(update);
          else counter.textContent = target.toLocaleString();
        }
        requestAnimationFrame(update);
        counter.dataset.animated = 'true';
      });
    }

    // Intersection Observer for animations
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          entry.target.classList.add('visible');
          if (entry.target.closest('.stats-grid')) animateCounters();
        }
      });
    }, { threshold: 0.2 });
    document.querySelectorAll('.animate').forEach(el => observer.observe(el));
  </script>
